import math

def op(a, b, n):
    # one–time construction per n -------------------------
    if not hasattr(op, '_cache'):
        op._cache = {}
    if n not in op._cache:
        # start with right projection
        tbl = [[j for j in range(n)] for _ in range(n)]

        def mul(x, y):
            return tbl[x][y]

        def eq1_holds():
            for x in range(n):
                for y in range(n):
                    for z in range(n):
                        u = mul(y, z)
                        v = mul(x, z)
                        w = mul(v, z)
                        q = mul(u, w)
                        r = mul(q, x)
                        if r != x:
                            return False
            return True

        def eq2_fails():
            for x in range(n):
                for y in range(n):
                    lhs = mul(mul(x, x), y)
                    rhs = mul(mul(x, x), mul(x, y))
                    if lhs != rhs:
                        return True
            return False

        # the original table satisfies EQ1 but not EQ2 – we need to break EQ2
        if not eq2_fails():
            # try every single-cell tweak
            for i in range(n):
                for j in range(n):
                    old = tbl[i][j]
                    for v in range(n):
                        if v == old:
                            continue
                        tbl[i][j] = v
                        if eq1_holds() and eq2_fails():
                            op._cache[n] = tbl
                            break
                    else:
                        tbl[i][j] = old
                        continue
                    break
                else:
                    continue
                break
        else:
            op._cache[n] = tbl

    # ------------------------------------------------------
    return op._cache[n][a][b]

