def op(a, b, n):
    # n must be a power of two (16, 32, …). Elements are 0..n-1.
    # We compute the n-element Laver table recursively.
    from functools import lru_cache
    if n & (n-1):
        raise ValueError('n must be a power of 2 for a Laver table')
    @lru_cache(maxsize=None)
    def star(A, B):  # 1-based indices internally
        if B == 1:
            return 1 if A == n else A + 1  # successor with wrap
        return star(star(A, B - 1), star(A, 1))
    return (star(a + 1, b + 1) - 1) % n

def op(a, b, n):
    # n must be a power of 2  (size of a Laver table)
    # Recursive definition:  x*1 = (x % n) + 1 ;  x*(y+1) = (x*y)*(x*y)
    # We build the table row-by-row the first time we see a given n,
    # memoising it in the global dict _LT so subsequent calls are O(1).
    global _LT
    if '_LT' not in globals():
        _LT = {}
    if n not in _LT:
        # build full table T_n
        T = [[0]*n for _ in range(n)]
        for x in range(n):
            T[x][0] = (x+1) % n  # x*1  (index 1 in math is 0 here)
        for y in range(1, n):
            for x in range(n):
                T[x][y] = T[T[x][y-1]][y-1]
        _LT[n] = T
    return _LT[n][a % n][b % n]
